function pd(s){const a=s.split('-').map(Number);return new Date(a[0],a[1]-1,a[2]);}
function fd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function addD(s,n){const d=pd(s);d.setDate(d.getDate()+n);return fd(d);}
function md(s){return s.slice(5).replace('-','/');}
function wdn(i){return '日一二三四五六'.charAt(i);}

function initialize(s){
  const b=s||{};
  if(Array.isArray(b.habits))return s;
  return {...b,habits:[
    {id:'h-sleep',name:'早睡',target:5},
    {id:'h-stretch',name:'拉伸',target:5},
    {id:'h-read',name:'阅读',target:5}
  ],logs:b.logs||{}};
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const size=ctx.size||'6x6';
  const wide=size==='6x3'||size==='6x6';
  const S=state||{};
  const habits=Array.isArray(S.habits)?S.habits:[];
  const logs=S.logs||{};
  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.flat().filter(k=>k!==null&&k!==undefined&&k!==false));
  const off=ui.off||0;
  const today=day();
  const days=[];
  for(let i=6;i>=0;i--)days.push(addD(today,-off*7-i));
  root.textContent='';

  const fail=(m)=>{ui.err=m;redraw();};
  const cnt=(id)=>days.filter(d=>(logs[id]||{})[d]).length;
  const total=(id)=>Object.keys(logs[id]||{}).length;
  const go=(n)=>{ui.off=Math.max(0,off+n);redraw();};
  const openEdit=(hb)=>{
    ui.view='edit';ui.err='';ui.confirmDel=false;
    ui.draft=hb?{id:hb.id,name:hb.name,target:hb.target}:{id:null,name:'',target:5};
    redraw();
  };
  const toggle=(id,date)=>{
    ui.err='';
    update(s=>{
      if(!(s.habits||[]).some(x=>x.id===id))return s;
      const lg={...(s.logs||{})};
      const m={...(lg[id]||{})};
      if(m[date])delete m[date];else m[date]=1;
      lg[id]=m;
      return {...s,logs:lg};
    }).catch(()=>fail('保存失败，请再试一次'));
  };


  function dayHead(){
    return h('div',{class:'wk'},
      wide?h('span',{class:'wk-pad'}):null,
      h('div',{class:'wk-days'},days.map(d=>{
        const dt=pd(d);
        return h('span',{class:'wd'+(d===today?' today':'')},
          h('span',{class:'w'},wdn(dt.getDay())),
          h('span',{class:'n'},String(dt.getDate())));
      })),
      wide?h('span',{class:'wk-pad'}):null);
  }

  function row(hb){
    const c=cnt(hb.id),t=hb.target,met=c>=t;
    const lg=logs[hb.id]||{};
    const cells=days.map(d=>{
      const on=!!lg[d];
      const dt=pd(d);
      const lab=hb.name+' '+(dt.getMonth()+1)+'月'+dt.getDate()+'日'+(d===today?'（今天）':'')+(on?' 已完成，点击取消':' 未完成，点击记为完成');
      return h('button',{type:'button',class:'cell'+(on?' on':'')+(d===today?' today':''),'aria-label':lab,title:lab,'aria-pressed':on?'true':'false',onclick:()=>toggle(hb.id,d)},on?'✓':null);
    });
    return h('div',{class:'row'+(met?' met':'')},
      h('button',{type:'button',class:'name',title:'编辑：'+hb.name,'aria-label':'编辑习惯 '+hb.name,onclick:()=>openEdit(hb)},
        h('span',{class:'nm'},hb.name),
        h('span',{class:'sub'},'累计 '+total(hb.id)+' 次')),
      h('div',{class:'cells'},cells),
      h('div',{class:'prog'},(met?'✓ ':'')+c+'/'+t));
  }

  function renderList(){
    const range=md(days[0])+'–'+md(days[6]);
    const head=h('div',{class:'hd'},
      h('div',{class:'ttl'},'习惯打卡'),
      h('div',{class:'nav'},
        h('button',{type:'button',class:'ib','aria-label':'查看更早的七天',onclick:()=>go(1)},'‹'),
        h('span',{class:'rng'},h('span',{class:'rt'},off===0?'近七天 ':off+'周前 '),h('span',{class:'rg'},range)),
        h('button',{type:'button',class:'ib',disabled:off===0,'aria-label':'查看较近的七天',onclick:()=>go(-1)},'›')),
      h('button',{type:'button',class:'add','aria-label':'添加习惯',onclick:()=>openEdit(null)},h('span',{class:'plus'},'＋'),h('span',{class:'addt'},'添加')));
    const err=ui.err?h('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
    let sum=0,goal=0;
    habits.forEach(x=>{sum+=cnt(x.id);goal+=x.target;});
    const body=habits.length
      ? h('div',{class:'list'},habits.map(row))
      : h('div',{class:'empty'},h('p',null,'还没有习惯'),h('button',{type:'button',class:'btn primary',onclick:()=>openEdit(null)},'添加第一个习惯'));
    const foot=habits.length?h('div',{class:'foot'},'这七天合计完成 '+sum+' / '+goal+' 次'):null;
    return [head,err,habits.length?dayHead():null,body,foot];
  }


  function renderEdit(){
    const d=ui.draft||{id:null,name:'',target:5};
    const isNew=!d.id;
    const nextUi={view:'list',draft:null,err:'',confirmDel:false,off:off};
    const back=()=>{ui.view='list';ui.draft=null;ui.err='';ui.confirmDel=false;redraw();};
    const save=()=>{
      const name=(d.name||'').trim();
      const t=Number(d.target);
      if(!name){fail('请填写习惯名称');return;}
      if(!(t>=1&&t<=7)){fail('每周目标需在 1–7 次之间');return;}
      if(habits.some(x=>x.id!==d.id&&x.name===name)){fail('已有同名习惯');return;}
      ui.err='';
      commit(s=>{
        const hs=s.habits||[];
        if(d.id)return {...s,habits:hs.map(x=>x.id===d.id?{...x,name:name,target:t}:x)};
        return {...s,habits:[...hs,{id:uid(),name:name,target:t}],logs:s.logs||{}};
      },nextUi).catch(()=>fail('保存失败，请再试一次'));
    };
    const del=()=>{
      commit(s=>{
        const lg={...(s.logs||{})};
        delete lg[d.id];
        return {...s,habits:(s.habits||[]).filter(x=>x.id!==d.id),logs:lg};
      },nextUi).catch(()=>fail('删除失败，请再试一次'));
    };
    const input=h('input',{class:'inp',type:'text',value:d.name||'',maxlength:'16',placeholder:'例如：早睡','aria-label':'习惯名称',
      oninput:()=>{d.name=input.value;},
      onkeydown:(e)=>{if(e&&e.key==='Enter')save();}});
    const chips=[1,2,3,4,5,6,7].map(n=>h('button',{type:'button',class:'chip'+(Number(d.target)===n?' on':''),'aria-pressed':Number(d.target)===n?'true':'false','aria-label':'每周 '+n+' 次',
      onclick:()=>{d.target=n;redraw();}},String(n)));
    const confirming=ui.confirmDel&&!isNew;
    const acts=confirming
      ? h('div',{class:'acts'},
          h('span',{class:'warn'},'删除后，该习惯的全部打卡记录也会清除。确定删除？'),
          h('span',{class:'grow'}),
          h('button',{type:'button',class:'btn',onclick:()=>{ui.confirmDel=false;redraw();}},'取消'),
          h('button',{type:'button',class:'btn primary',onclick:del},'确认删除'))
      : h('div',{class:'acts'},
          isNew?null:h('button',{type:'button',class:'btn',onclick:()=>{ui.confirmDel=true;redraw();}},'删除'),
          h('span',{class:'grow'}),
          h('button',{type:'button',class:'btn',onclick:back},'取消'),
          h('button',{type:'button',class:'btn primary',onclick:save},'保存'));
    return [
      h('div',{class:'hd'},
        h('button',{type:'button',class:'ib','aria-label':'返回',onclick:back},'‹'),
        h('div',{class:'ttl show'},isNew?'添加习惯':'编辑习惯')),
      h('div',{class:'form'},
        h('label',{class:'fld'},h('span',{class:'lb'},'习惯名称'),input),
        h('div',{class:'fld'},h('span',{class:'lb'},'每周目标次数'),h('div',{class:'chips'},chips),h('span',{class:'hint'},'每天最多记一次，所以最多 7 次')),
        ui.err?h('div',{class:'err',role:'alert'},'⚠ '+ui.err):null),
      acts];
  }

  const nodes=ui.view==='edit'?renderEdit():renderList();
  nodes.filter(n=>n).forEach(n=>root.appendChild(n));
}

